<template><form class="space-y-6" @submit.prevent="submit"><div class="grid gap-6 xl:grid-cols-3"><section class="card space-y-4 p-5 xl:col-span-2"><h2 class="font-display text-xl font-extrabold text-navy">Order Details</h2><div class="grid gap-4 md:grid-cols-3"><FormInput label="PO Date" type="date" v-model="form.po_date"/><FormSelect label="Status" v-model="form.status" :options="statuses"/><FormSelect label="Customer" v-model="form.customer_id" :options="customers"/></div><div class="grid gap-4 md:grid-cols-3"><FormSelect label="Sales Agent" v-model="form.sales_agent_id" :options="salesAgents"/><FormSelect label="Payment Terms" v-model="form.payment_term_id" :options="paymentTerms"/><FormInput label="Location / Branch" v-model="form.location"/></div></section><section class="card space-y-4 p-5"><h2 class="font-display text-xl font-extrabold text-navy">Logistics Setup</h2><FormSelect label="Operational Area" v-model="form.operational_area_id" :options="operationalAreas"/><FormSelect label="Transport Mode" v-model="form.transport_mode" :options="transportModes"/><FormInput label="Truck / Vessel Identifier" v-model="form.truck_or_vessel_identifier"/></section></div><section class="card p-5"><div class="mb-4 flex items-center justify-between"><h2 class="font-display text-xl font-extrabold text-navy">Item Details</h2><button type="button" class="btn-secondary" @click="addItem">Add Item</button></div><div class="space-y-3"><div v-for="(item,index) in form.items" :key="index" class="grid gap-3 rounded-lg border border-slate-200 p-3 md:grid-cols-6"><FormSelect class="md:col-span-2" label="Product" v-model="item.product_id" :options="products"/><FormInput label="Quantity" type="number" v-model="item.quantity"/><FormInput label="UOM" v-model="item.uom"/><FormInput label="Unit Price" type="number" v-model="item.unit_price"/><div><div class="label">Total</div><div class="pt-3 font-bold text-navy">{{ lineTotal(item) }}</div></div></div></div><div class="mt-5 text-right font-display text-3xl font-extrabold text-navy">Grand Total: ₱ {{ grandTotal }}</div></section><div class="sticky bottom-16 flex gap-3 bg-surface/90 py-4 lg:bottom-0"><button class="btn-secondary flex-1" type="button" @click="saveDraft">Save Draft</button><button class="btn-primary flex-1">Save & Print Official SO</button></div></form></template>
<script>import { Inertia } from '@inertiajs/inertia'; import FormInput from '../FormInput.vue'; import FormSelect from '../FormSelect.vue'; export default{components:{FormInput,FormSelect},props:{order:Object,customers:Array,products:Array,paymentTerms:Array,salesAgents:Array,operationalAreas:Array,statuses:Array,transportModes:Array},data(){return{form:this.order?{...this.order,items:this.order.items}:{po_date:new Date().toISOString().slice(0,10),status:'Pending Approval',customer_id:'',sales_agent_id:'',payment_term_id:'',location:'',operational_area_id:'',transport_mode:'Truck',truck_or_vessel_identifier:'',notes:'',items:[{product_id:'',description:'',quantity:1,uom:'BAGS',unit_price:0}]}}},computed:{grandTotal(){return this.form.items.reduce((sum,item)=>sum+Number(this.lineTotal(item)),0).toFixed(2)}},methods:{addItem(){this.form.items.push({product_id:'',description:'',quantity:1,uom:'BAGS',unit_price:0})},lineTotal(item){return (Number(item.quantity || 0)*Number(item.unit_price || 0)).toFixed(2)},saveDraft(){this.form.status='Draft';this.submit()},submit(){if(this.order){Inertia.put(`/sales-orders/${this.order.id}`,this.form)}else{Inertia.post('/sales-orders',this.form)}}}}</script>